def compute(vars):
    average_operating_income = (vars["v1"] + vars["v2"]) / 2
    return {
        "value": average_operating_income,
        "trace": {
            "operating_income_2018": vars["v1"],
            "operating_income_2019": vars["v2"],
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": None
            }
        }
    }
